/* ===== module: formulas/rep-max-table.js ===== */
/* FORK (Research Round 2 #9): the rep-max table core for exercise
   pages — for each rep count the user has actually attempted, their
   best weight at that count and the best estimated 1RM a set at that
   count produced. Pure functions only (no DOM, no state) so the unit
   suite can load this file alone; the exercise-page card that renders
   it is the wiring step that follows.

   forkRepMaxTable(logs) — logs are workout-log entries for ONE
   exercise, each { date, sets: [{ w, r, rpe? }] } in any order.
   Returns rows sorted by reps ascending:
     [{ reps, bestWeight, bestE1RM, date }]
   Only rep counts with at least one set carrying a real weight and
   rep count appear — the table never invents a row.
   FORK v1.992.21 (P2-7, D7): warm-up sets COUNT here, exactly as they
   count in Stats — one counting rule for warm-up sets across both
   surfaces. Until this build the core skipped any set carrying a
   `warmup` flag, so Stats counted warm-ups while this table silently
   dropped them (fix-list S3 #22). The flag is no longer read; the
   exercise page's coordinator adaptation no longer stamps it.
   FORK v1.991.67 (R7, fix-list item 16): bestE1RM is the app's ONE
   estimate — the same RPE-aware Epley as estimate1RM in
   formulas/e1rm.js, mirrored here in miniature so this module stays
   loadable on its own (the two must not drift: RPE folds in through
   RIR = 10 − RPE, clamped to [0,10]; effective reps (reps + RIR)
   capped at 15). Before this, the table ran plain Epley with a
   12-rep cap and a 1-rep special case, so the same set printed one
   number in the table (210 for 185×4@8) and another in the page's
   PROJECTED 1RM headline (222) with nothing saying why. Now a set's
   estimate is identical in both places; the headline additionally
   names its basis (the heaviest set), and the anchor set's own row
   here shows the headline number. */
(function () {
  function repMaxE1RM(weight, reps, rpe) {
    const w = Number(weight) || 0, r = Number(reps) || 0;
    if (w <= 0 || r <= 0) return 0;
    const rpeNum = rpe == null || rpe === '' ? NaN : Number(rpe);
    const rir = Number.isFinite(rpeNum) ? Math.max(0, 10 - Math.min(10, Math.max(0, rpeNum))) : 0;
    return w * (1 + Math.min(r + rir, 15) / 30);
  }
  function forkRepMaxTable(logs) {
    const byReps = new Map();
    (Array.isArray(logs) ? logs : []).forEach(log => {
      (log && Array.isArray(log.sets) ? log.sets : []).forEach(set => {
        if (!set) return; /* FORK v1.992.21 (P2-7, D7): no warm-up exclusion — warm-ups are sets and count, as in Stats. */
        const reps = Math.floor(Number(set.r) || 0);
        const w = Number(set.w) || 0;
        if (reps <= 0 || w <= 0) return;
        const e = repMaxE1RM(w, reps, set.rpe);
        const cur = byReps.get(reps);
        if (!cur || w > cur.bestWeight) {
          byReps.set(reps, { reps, bestWeight: w, bestE1RM: Math.max(e, cur ? cur.bestE1RM : 0), date: log.date || null });
        } else if (e > cur.bestE1RM) {
          cur.bestE1RM = e;
        }
      });
    });
    return [...byReps.values()].sort((a, b) => a.reps - b.reps);
  }
  if (typeof module !== 'undefined' && module.exports) module.exports = { forkRepMaxTable, repMaxE1RM };
  if (typeof window !== 'undefined') { window.forkRepMaxTable = forkRepMaxTable; window.repMaxE1RM = repMaxE1RM; }
})();
